function invalidate(){state.valid=false;if(window.MatchReview)window.MatchReview.stale();state.prepared=null;invalidateEvaluation();$('results').classList.add('hidden');$('empty').classList.remove('hidden');$('reviewExport').hidden=true;$('downloadCsv').disabled=true;$('downloadAll').disabled=true;}
function cleanId(name,normalize=true){let id=name.replace(/^.*[\\/]/,'').replace(/\.txt$/i,'');if(normalize&&/\.rf\.[A-Za-z0-9_-]+$/i.test(id)){id=id.replace(/\.rf\.[A-Za-z0-9_-]+$/i,'').replace(/(?:\.(?:png|jpe?g|webp|bmp)|_(?:png|jpe?g|webp|bmp))$/i,'');}return id;}
