async function loadFiles(side,files){state.busy++;if(side==='gold')invalidateEvaluation();else invalidate();updateCounts();$('progress').textContent='Đang đọc nhãn / ZIP…';hideMessage();try{const loaded=await collectLabels(files,side);state[side]=loaded.files;if(side==='before'||side==='after')state.matchReviews.clear();nameMap(loaded.files);if(side==='after'&&loaded.yaml&&!currentNames()){const names=parseClassNames(loaded.yaml.text);names.forEach((v,i)=>$('class'+i).value=v);$('classesName').textContent='Đã lấy tên lớp từ '+loaded.yaml.path;state.classes=names;}if(side==='gold')$('goldCount').textContent=loaded.files.length+' file nhãn tham chiếu';}catch(e){state[side]=[];if(side==='gold')$('goldCount').textContent='Chưa có nhãn hợp lệ';tell(e.message,true);}finally{state.busy--;updateCounts();$('progress').textContent='';window.dispatchEvent(new CustomEvent('yolo:labels-updated',{detail:{side}}));}}
function parseCSV(text){text=text.replace(/^\uFEFF/,'');const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else if(quoted)quoted=false;else if(cell==='')quoted=true;else throw Error('CSV có dấu ngoặc kép sai định dạng.');}else if(c===','&&!quoted){row.push(cell);cell='';}else if((c==='\r'||c==='\n')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x!==''))rows.push(row);row=[];cell='';}else cell+=c;}if(quoted)throw Error('CSV thiếu dấu ngoặc kép đóng.');if(cell!==''||row.length){row.push(cell);if(row.some(x=>x!==''))rows.push(row);}if(!rows.length)throw Error('CSV rỗng.');const fields=rows.shift();if(new Set(fields).size!==fields.length)throw Error('CSV có tên cột trùng.');return {fields,rows:rows.map((r,i)=>{if(r.length!==fields.length)throw Error('CSV sai số cột ở dòng '+(i+2));return Object.fromEntries(fields.map((f,j)=>[f,r[j]]));})};}
