function classLabel(id,names=state.classes){return id===''||id===null?'':names?`${names[Number(id)]} (ID ${id})`:`ID ${id}`;}
function enrichEvents(events,names){return events.map(e=>{const before=e.before?Number(e.before.split(/\s+/)[0]):'',after=e.after?Number(e.after.split(/\s+/)[0]):'';return {...e,before_class_id:before,before_class_name:before!==''&&names?names[before]:'',after_class_id:after,after_class_name:after!==''&&names?names[after]:'',class_transition:e.class_changed?`${classLabel(before,names)} → ${classLabel(after,names)}`:''};});}
