 const removed=new Set(review.removed||[]),added=new Set(review.added||[]),banned=new Set((review.rejected||[]).map(p=>p.before_line+':'+p.after_line));
 for(const line of removed)if(!ai.has(line))throw Error('Quyết định xóa tham chiếu dòng cũ không tồn tại: '+line);
