 for(const p of review.links||[]){const i=ai.get(p.before_line),j=bj.get(p.after_line);if(i===undefined||j===undefined||usedA.has(i)||usedB.has(j)||removed.has(p.before_line)||added.has(p.after_line))throw Error('Quyết định ghép bị trùng/xung đột hoặc dòng không còn tồn tại.');usedA.add(i);usedB.add(j);pinned.push([i,j,iou(a[i],b[j]),true]);}
 const result=automatic.filter(([i,j])=>!usedA.has(i)&&!usedB.has(j)&&!removed.has(a[i].line)&&!added.has(b[j].line)&&!banned.has(a[i].line+':'+b[j].line)).map(p=>[...p,false]);
 return [...result,...pinned];
