 if(JSON.stringify(currentNames()||CANONICAL)!==JSON.stringify(CANONICAL))add('','CLASS_MAPPING','ERROR','classes.yaml must contain four canonical names in order');
 let ids=[...prepared.map.keys()];if(state.manifest&&state.manifestScope!=='all'){const reviewer=state.selectedMember||$('reviewer').value.trim();ids=state.manifest.rows.filter(r=>!r.assigned_reviewer_id||r.assigned_reviewer_id.trim()===reviewer).map(r=>scopeId(r.image_id));if(ids.length!==new Set(ids).size)add('','DUPLICATE_ID','ERROR','manifest contains repeated IDs');const expected=new Set(ids);for(const id of prepared.map.keys())if(!expected.has(id))add(id,'EXTRA_LABEL','ERROR','label ID not assigned/approved for use');}
 for(const id of ids){if(!prepared.map.has(id)){add(id,'LABEL_MISSING','ERROR','missing matching TXT');continue;}const {boxes,errors}=qcParseLabels(prepared.map.get(id));for(const e of errors)add(id,'YOLO_FORMAT','ERROR',e);if(new Set(boxes.map(b=>JSON.stringify([b.c,...b.g]))).size!==boxes.length)add(id,'DUPLICATE_BOX','WARNING','identical boxes; inspect visually');if(!boxes.length)add(id,'EMPTY_LABEL','INFO','empty TXT must be verified visually');}
 download('qc_labels_report.csv',new Blob([csv(['image_id','check_code','severity','message','resolution','decision_id'],report)],{type:'text/csv;charset=utf-8'}));tell(`QC nhãn: ${report.filter(x=>x.severity==='ERROR').length} lỗi, ${report.filter(x=>x.severity==='WARNING').length} cảnh báo. Đây chưa phải QC bàn giao toàn nhóm.`);
